import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Default Checklists","description":"Hearth pre-approval checks, pre-completion checks, and task coverage boundaries.","frontmatter":{"title":"Default Checklists","description":"Hearth pre-approval checks, pre-completion checks, and task coverage boundaries.","outline":[2]},"headers":[],"relativePath":"en/reference/checklists.md","filePath":"en/reference/checklists.md","lastUpdated":1794305977000}'),r={name:"en/reference/checklists.md"};function o(s,e,l,c,d,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="default-checklists" tabindex="-1">Default Checklists <a class="header-anchor" href="#default-checklists" aria-label="Permalink to &quot;Default Checklists&quot;">​</a></h1><p class="lead">Checklists belong in task templates, approval screens, and acceptance flows, not only in documentation. They help the user confirm that the system has not mistaken &quot;looks finished&quot; for &quot;really finished&quot;.</p><h2 id="before-approval-and-completion" tabindex="-1">Before Approval and Completion <a class="header-anchor" href="#before-approval-and-completion" aria-label="Permalink to &quot;Before Approval and Completion&quot;">​</a></h2><p>Before an external action happens, confirm:</p><ul><li>[ ] The action type matches the real intent;</li><li>[ ] The goal&#39;s acceptance criteria, constraints, and forbidden actions were checked;</li><li>[ ] The recipient, file, account, device, or resource is correct;</li><li>[ ] The content and attachments are correct;</li><li>[ ] The action does not exceed the current authorization scope;</li><li>[ ] Reversibility and likely impact are explained;</li><li>[ ] Approval is still valid and has not been replayed;</li><li>[ ] Approval binds the resolved real action and parameter fingerprint; changed parameters invalidate it;</li><li>[ ] Failure, retry, and reconciliation paths are ready;</li><li>[ ] No network, credential, or safety boundary is bypassed.</li></ul><p>Reading and organizing may be authorized within the task scope. Sending, publishing, deleting, paying, and operating devices need explicit confirmation. Irreversible actions stay bounded by target, amount, or time even when pre-authorized.</p><p>Before a task is marked complete, confirm:</p><ul><li>[ ] The target artifact exists and the user can find it;</li><li>[ ] Every goal acceptance criterion has a verdict and evidence reference;</li><li>[ ] A verifier passed; the executor saying so is not enough;</li><li>[ ] Key facts have sources, and changes have diffs or versions;</li><li>[ ] No unauthorized external effect occurred;</li><li>[ ] External actions have receipts, and uncertain results were reconciled;</li><li>[ ] Uncertain effects entered an explicit reconciliation queue and have a user decision;</li><li>[ ] Failures, skipped work, and open items are explained;</li><li>[ ] Tokens, time, human minutes, and cost are recorded;</li><li>[ ] Workspaces, temporary authority, and execution rights are released;</li><li>[ ] Handoffs carry a generation and evidence, and old-generation results did not advance new state;</li><li>[ ] Sandbox path, network, process, and credential boundaries were not bypassed, and escape attempts failed closed;</li><li>[ ] The user can inspect, undo, retry, or continue.</li></ul><h2 id="coverage-boundaries" tabindex="-1">Coverage Boundaries <a class="header-anchor" href="#coverage-boundaries" aria-label="Permalink to &quot;Coverage Boundaries&quot;">​</a></h2><p>Hearth does not promise &quot;every application, every scenario, 100% unattended&quot;. It promises end-to-end coverage for selected personal digital work, safe handoff when work cannot be completed reliably, and evidence, permission records, and receipts for every completion.</p><table tabindex="0"><thead><tr><th>Maturity</th><th>Meaning</th></tr></thead><tbody><tr><td>Can attempt</td><td>The system can enter the task family and produce a draft</td></tr><tr><td>Can complete</td><td>Representative tasks pass verification</td></tr><tr><td>Can rely on</td><td>Repeated real use is stable and failures are recoverable</td></tr><tr><td>Can act proactively</td><td>Work starts without human triggering inside the authorized scope</td></tr><tr><td>Can run unattended</td><td>It runs for a long time with controlled risk</td></tr></tbody></table><p>&quot;Can attempt&quot; is not &quot;can rely on&quot;, and &quot;can complete&quot; is not &quot;can run unattended&quot;. Phase acceptance follows real tasks and evidence, not feature names.</p>',12)])])}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
